    private static HashMap<String, ArrayList<String>> packages = new HashMap<String, ArrayList<String>>();

    private ClassList() throws JepException {
        loadClassPath();
        loadPackages();
        loadClassList();
    }

    /**
     * load jar files from class path
     * 
